# Ghidra PyGhidra/CPython 3 headless script, run only on the compiled, stripped ELF.
# The export is *Ghidra's* pseudocode, not code generated by EdgeAI itself.
#@category EdgeAI
import os
import re
import json
import codecs
from ghidra.app.decompiler import DecompInterface

args = getScriptArgs()
if len(args) != 1:
    raise ValueError("Expected one output directory")
dest = args[0]
if not os.path.isdir(dest):
    os.makedirs(dest)
decompiler = DecompInterface()
decompiler.openProgram(currentProgram)
manager = currentProgram.getFunctionManager()
listing = manager.getFunctions(True)
records = []
counter = 0
while listing.hasNext():
    fn = listing.next()
    if fn.isExternal():
        continue
    counter += 1
    addr = str(fn.getEntryPoint())
    is_thunk = bool(fn.isThunk())
    name = fn.getName()
    try:
        output = decompiler.decompileFunction(fn, 40, monitor)
        if output is not None and output.decompileCompleted():
            result = output.getDecompiledFunction()
            source = str(result.getC()) if result is not None else None
            if source and source.strip():
                safe = re.sub(r'[^a-zA-Z0-9_.-]', '_', name)[:52]
                filename = "%04d_%s_%s.c" % (counter, addr, safe)
                with codecs.open(os.path.join(dest, filename), "w", "utf-8") as stream:
                    stream.write(source)
                records.append({"entry": addr, "name": name, "status": "GHIDRA_PSEUDOCODE",
                                "file": filename, "bytes": len(source),
                                "thunk": is_thunk})
                continue
        records.append({"entry": addr, "name": name, "status": "GHIDRA_FAILED",
                        "reason": "decompilation returned no C", "thunk": is_thunk})
    except Exception as exc:
        records.append({"entry": addr, "name": name, "status": "GHIDRA_FAILED",
                        "reason": str(exc)[:160], "thunk": is_thunk})
decompiler.dispose()
manifest = {
    "backend": "Ghidra 12.1.3 external decompiler (not EdgeAI native)",
    "target_source_read": False,
    "recompiled": False,
    "behavioral_equivalence_proven": False,
    "functions_detected": len(records),
    "pseudocode_functions": sum(1 for item in records if item["status"] == "GHIDRA_PSEUDOCODE"),
    "functions": records
}
with codecs.open(os.path.join(dest, "manifest.json"), "w", "utf-8") as stream:
    stream.write(json.dumps(manifest, indent=2, sort_keys=True))
print("EDGEAI_GHIDRA_EXPORTED=%d" % manifest["pseudocode_functions"])
